// Build the task queue from the MQTT topic + payload, emit the first
// request frame as msg.payload (Buffer) so the serial-request node can
// send it. Subsequent steps are driven by the controller node.

function buildFrame(cmd, data) {
    const len = data.length;
    const body = [cmd[0], cmd[1], len, ...data];
    let chk = 0xAD;
    for (const b of body) chk = (chk + b) & 0xFF;
    body.push(chk);
    const escaped = [];
    for (const b of body) {
        escaped.push(b);
        if (b === 0x07) escaped.push(0x07);
    }
    return Buffer.from([0x07, 0xF0, ...escaped, 0x07, 0x0F]);
}

function levelFromPayload(p) {
    const map = { 'away': 1, 'low': 2, 'medium': 3, 'high': 4,
                  '1': 1, '2': 2, '3': 3, '4': 4 };
    const lvl = map[String(p).toLowerCase()] ?? Number(p);
    if (![1, 2, 3, 4].includes(lvl)) throw new Error('bad level: ' + p);
    return lvl;
}

const topic = msg.topic || '';
const action = topic.split('/').pop();

let queue;
try {
    if (action === 'read') {
        queue = [
            { cmd: [0x00, 0x69], decoder: 'firmware',     resKey: 'firmware' },
            { cmd: [0x00, 0xD1], decoder: 'temperatures', resKey: 'temperatures' },
            { cmd: [0x00, 0x0B], decoder: 'fans',         resKey: 'fans' },
            { cmd: [0x00, 0xCD], decoder: 'ventLevels',   resKey: 'ventLevels' },
            { cmd: [0x00, 0xDD], decoder: 'hours',        resKey: 'hours' },
            { cmd: [0x00, 0x0D], decoder: 'raw',          resKey: 'bypassRaw' },
            { cmd: [0x00, 0xD9], decoder: 'raw',          resKey: 'errorsRaw' }
        ];
    } else if (action === 'level') {
        queue = [{ cmd: [0x00, 0x99], data: [levelFromPayload(msg.payload)], setOnly: true }];
    } else if (action === 'comforttemp') {
        const t = Number(msg.payload);
        if (!(t >= 12 && t <= 28)) throw new Error('temp out of range: ' + msg.payload);
        queue = [{ cmd: [0x00, 0xD3], data: [Math.round((t + 20) * 2)], setOnly: true,
                   meta: { temp: t } }];
    } else if (action === 'resetfilter') {
        queue = [{ cmd: [0x00, 0xDB], data: [0, 0, 1, 0], setOnly: true }];
    } else {
        throw new Error('unknown action: ' + topic);
    }
} catch (e) {
    node.error('comfoair parse: ' + e.message, msg);
    return null;
}

const current = queue.shift();
msg.comfoair = { action: action, queue: queue, results: {}, current: current };
msg.payload = buildFrame(current.cmd, current.data || []);
return msg;

// Drives one step of the protocol: parse the bytes the unit sent us,
// validate, decode, store, and either emit the next request or the
// final aggregated result. When the response contained a frame (not
// just an ACK), output 1 emits an ACK back to the unit.
//
// Outputs:
//   0 -> serial request (next request frame)
//   1 -> serial out     (ACK back to unit, when applicable)
//   2 -> mqtt out / debug (final result)

const sym = msg.comfoair;
if (!sym) {
    node.warn('controller: no msg.comfoair (keepMsgProperties off?)');
    return [null, null, { payload: { ok: false, error: 'lost state' },
                          topic: 'red/cmd/comfoair/result' }];
}

function buildFrame(cmd, data) {
    const len = data.length;
    const body = [cmd[0], cmd[1], len, ...data];
    let chk = 0xAD;
    for (const b of body) chk = (chk + b) & 0xFF;
    body.push(chk);
    const out = [];
    for (const b of body) {
        out.push(b);
        if (b === 0x07) out.push(0x07);
    }
    return Buffer.from([0x07, 0xF0, ...out, 0x07, 0x0F]);
}

function parseResponse(buf) {
    // Find ACK and/or one response frame in the received buffer.
    let ack = false;
    let frame = null;
    let i = 0;
    while (i + 1 < buf.length) {
        if (buf[i] === 0x07 && buf[i + 1] === 0xF3) { ack = true; i += 2; continue; }
        if (buf[i] === 0x07 && buf[i + 1] === 0xF0) {
            const start = i;
            let e = i + 2;
            let found = false;
            while (e + 1 < buf.length) {
                if (buf[e] === 0x07) {
                    if (buf[e + 1] === 0x07) { e += 2; continue; }
                    if (buf[e + 1] === 0x0F) { found = true; break; }
                }
                e++;
            }
            if (!found) { i++; continue; }
            const inner = buf.slice(start + 2, e);
            const body = [];
            for (let j = 0; j < inner.length; j++) {
                body.push(inner[j]);
                if (inner[j] === 0x07 && inner[j + 1] === 0x07) j++;
            }
            if (body.length >= 4) {
                const length = body[2];
                if (3 + length < body.length) {
                    const payload = Buffer.from(body.slice(3, 3 + length));
                    const chk = body[3 + length];
                    let exp = 0xAD;
                    for (let j = 0; j < 3 + length; j++) exp = (exp + body[j]) & 0xFF;
                    if (chk === exp) frame = { cmd: [body[0], body[1]], payload };
                }
            }
            i = e + 2;
            continue;
        }
        i++;
    }
    return { ack, frame };
}

function decode(name, p) {
    if (name === 'firmware') {
        const ver = p[0] + '.' + p[1] + '.' + p[2];
        const name = p.slice(3, 13).toString('ascii').replace(/[\x00 ]+$/, '');
        return name ? ver + ' (' + name + ')' : ver;
    }
    if (name === 'temperatures') {
        const t = (b) => b / 2 - 20;
        return { comfort: t(p[0]), outsideAir: t(p[1]), supplyAir: t(p[2]),
                 returnAir: t(p[3]), exhaustAir: t(p[4]) };
    }
    if (name === 'fans') {
        const sup = (p[2] << 8) | p[3];
        const exh = (p[4] << 8) | p[5];
        return { supplyPct: p[0], exhaustPct: p[1],
                 supplyRpm: sup ? Math.round(1875000 / sup) : 0,
                 exhaustRpm: exh ? Math.round(1875000 / exh) : 0 };
    }
    if (name === 'ventLevels') {
        return {
            exhaustAway: p[0], exhaustLow: p[1], exhaustMedium: p[2],
            supplyAway: p[3], supplyLow: p[4], supplyMedium: p[5],
            currentExhaust: p[6], currentSupply: p[7],
            currentLevel: p[8],
            highEnabled: !!(p.length > 9 ? p[9] : 0),
            exhaustHigh: p.length > 10 ? p[10] : 0,
            supplyHigh:  p.length > 11 ? p[11] : 0
        };
    }
    if (name === 'hours') {
        const u24 = (o) => (p[o] << 16) | (p[o + 1] << 8) | p[o + 2];
        return {
            away: u24(0), low: u24(3), medium: u24(6),
            high:   p.length >= 18 ? u24(15) : 0,
            filter: p.length >= 17 ? ((p[15] << 8) | p[16]) : 0
        };
    }
    if (name === 'raw') {
        return Array.from(p).map(b => b.toString(16).padStart(2, '0')).join(' ');
    }
    return null;
}

function finalResult(payload) {
    return { payload: payload, topic: 'red/cmd/comfoair/result' };
}

const buf = Buffer.isBuffer(msg.payload) ? msg.payload : Buffer.from(msg.payload || []);
const parsed = parseResponse(buf);

const current = sym.current;
if (current.setOnly) {
    if (!parsed.ack && !parsed.frame) {
        return [null, null, finalResult({ ok: false, action: sym.action,
                                          error: 'no ACK', raw: buf.toString('hex') })];
    }
} else {
    if (!parsed.frame) {
        return [null, null, finalResult({ ok: false, action: sym.action,
                                          step: current.resKey,
                                          error: 'no response frame',
                                          raw: buf.toString('hex') })];
    }
    const expected = [current.cmd[0], (current.cmd[1] + 1) & 0xFF];
    if (parsed.frame.cmd[0] !== expected[0] || parsed.frame.cmd[1] !== expected[1]) {
        return [null, null, finalResult({ ok: false, action: sym.action,
                                          step: current.resKey,
                                          error: 'unexpected response cmd',
                                          got: parsed.frame.cmd, want: expected })];
    }
    sym.results[current.resKey] = decode(current.decoder, parsed.frame.payload);
}

// If the unit sent a response frame, we should ACK it back.
const ackOut = parsed.frame ? { payload: Buffer.from([0x07, 0xF3]) } : null;

if (sym.queue.length > 0) {
    const next = sym.queue.shift();
    sym.current = next;
    msg.payload = buildFrame(next.cmd, next.data || []);
    return [msg, ackOut, null];
}

const result = { ok: true, action: sym.action };
if (sym.action === 'read') Object.assign(result, sym.results);
if (current.meta) Object.assign(result, current.meta);
if (sym.action === 'level') {
    const map = { 1: 'away', 2: 'low', 3: 'medium', 4: 'high' };
    const lvl = current.data[0];
    result.level = lvl;
    result.levelName = map[lvl];
}
return [null, ackOut, finalResult(result)];
